#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

# Roda sempre a partir da raiz do projeto, para o .env cair no lugar certo.
cd "$(dirname "${BASH_SOURCE[0]}")/.."
grep -qxF '.env' .gitignore 2>/dev/null || printf '.env\n' >> .gitignore

# As chaves vão para o curl por stdin (-K -), então nunca aparecem em `ps` nem na tela.
check_google() {
  printf 'header = "X-Goog-Api-Key: %s"\nheader = "X-Goog-FieldMask: places.id"\nheader = "Content-Type: application/json"\n' "$1" |
    curl -s -o /dev/null -w '%{http_code}' -K - -X POST \
      --data '{"textQuery":"Lagoa da Conceicao Florianopolis","pageSize":1}' \
      https://places.googleapis.com/v1/places:searchText
}
check_groq() {
  printf 'header = "Authorization: Bearer %s"\n' "$1" |
    curl -s -o /dev/null -w '%{http_code}' -K - https://api.groq.com/openai/v1/models
}
check_ors() {
  printf 'header = "Authorization: %s"\nheader = "Content-Type: application/json"\n' "$1" |
    curl -s -o /dev/null -w '%{http_code}' -K - -X POST \
      --data '{"locations":[[-48.5482,-27.5954],[-48.4642,-27.5969]]}' \
      https://api.openrouteservice.org/v2/matrix/foot-walking
}

# capture_key VAR "Prompt" checker: lê (oculto), testa com uma chamada barata e
# só devolve sucesso se o teste der HTTP 200. Nada é gravado antes de validar.
capture_key() {
  local var="$1" prompt="$2" checker="$3" code
  while true; do
    ask_secret "$var" "$prompt"
    if [[ -z "${!var}" ]]; then warn "valor vazio."; continue; fi
    printf '  %s… testando a chave%s\n' "$DIM" "$RESET"
    code=$("$checker" "${!var}" 2>/dev/null) || code=000
    if [[ "$code" == 200 ]]; then
      printf '  %s✓ chave válida%s\n' "$GREEN" "$RESET"
      return 0
    fi
    warn "o teste falhou (HTTP $code): chave errada, API não ativada ou restrição incorreta."
    note "Chaves recém-criadas podem levar alguns minutos para valer."
    confirm "Tentar de novo?" || { SKIPPED+=("$var não validada (rode o wizard de novo)"); return 1; }
  done
}

banner "turista-viajante: chaves de API"

# ── 1/6 ───────────────────────────────────────────────────────────────────
stage "Google Cloud: projeto e billing"
say "A Places API (New) exige um projeto com billing ativo (cartão), mas tem"
say "cota grátis mensal por SKU. Vamos configurar um teto de gasto já já."
open_url "https://console.cloud.google.com/projectcreate"
step "Crie um projeto chamado 'turista-viajante' e selecione-o no topo da página."
open_url "https://console.cloud.google.com/billing"
step "Vincule uma conta de faturamento ao projeto (crie uma, se não tiver)."
pause "Projeto criado e com billing vinculado? Enter para continuar"

# ── 2/6 ───────────────────────────────────────────────────────────────────
stage "Google Cloud: ativar a Places API (New)"
open_url "https://console.cloud.google.com/apis/library/places.googleapis.com"
step "Confirme que o projeto 'turista-viajante' está selecionado."
step "Confirme que o nome é 'Places API (New)' e clique em Ativar (Enable)."
warn "Não ative só 'Places API' (a antiga): o projeto usa a versão (New)."
pause "API ativada? Enter para continuar"

# ── 3/6 ───────────────────────────────────────────────────────────────────
stage "Google Cloud: criar e restringir a chave"
open_url "https://console.cloud.google.com/apis/credentials"
step "Create credentials → API key."
step "No diálogo, clique em 'Restrict key' (ou edite a chave depois)."
step "Em 'API restrictions' marque 'Restrict key' e selecione só 'Places API (New)'."
step "Application restrictions: deixe 'None' (uso local). Salve e copie a chave."
if capture_key GOOGLE_PLACES_API_KEY "Cole a chave do Google (oculta):" check_google; then
  write_env GOOGLE_PLACES_API_KEY "$GOOGLE_PLACES_API_KEY"
fi

# ── 4/6 ───────────────────────────────────────────────────────────────────
stage "Google Cloud: limite de gasto"
warn "Um orçamento (budget) só AVISA por e-mail: ele não bloqueia a cobrança."
open_url "https://console.cloud.google.com/billing/budgets"
step "Create budget: valor baixo (ex.: US\$ 5), alertas em 50%, 90% e 100%."
open_url "https://console.cloud.google.com/apis/api/places.googleapis.com/quotas"
step "Aqui dá para impor um TETO: edite as cotas diárias de requisições (Edit quota)."
note "Não tenho certeza dos nomes exatos das cotas na UI atual. Se não achar,"
note "pule: o orçamento com alertas já cobre o essencial no começo."
pause "Alerta (e, se possível, cota) configurados? Enter para continuar"

# ── 5/6 ───────────────────────────────────────────────────────────────────
stage "Groq: LLM open-weight grátis"
say "Groq serve modelos abertos (Llama, Qwen, gpt-oss) de graça, sem cartão."
open_url "https://console.groq.com/keys"
step "Entre (ou crie conta), clique em 'Create API Key', dê um nome e copie."
note "Alternativa: OpenRouter (modelos ':free'). Se preferir, me avise depois."
if capture_key GROQ_API_KEY "Cole a chave da Groq (oculta):" check_groq; then
  write_env GROQ_API_KEY "$GROQ_API_KEY"
fi

# ── 6/6 ───────────────────────────────────────────────────────────────────
stage "OpenRouteService: matriz de tempos"
open_url "https://openrouteservice.org/dev/#/signup"
step "Crie a conta e confirme o e-mail."
open_url "https://openrouteservice.org/dev/#/home"
step "Em 'Request a token', crie um token (plano Standard, grátis) e copie."
if capture_key ORS_API_KEY "Cole o token do ORS (oculto):" check_ors; then
  write_env ORS_API_KEY "$ORS_API_KEY"
fi

finish
